void rotate(int[][] m) {
    int n = m.length;
    for (int r = 0; r < n; r++)
        for (int c = r + 1; c < n; c++) {    // c > r: swap each pair ONCE
            int t = m[r][c]; m[r][c] = m[c][r]; m[c][r] = t;
        }
    for (int[] row : m)
        for (int l = 0, rr = n - 1; l < rr; l++, rr--) { int t = row[l]; row[l] = row[rr]; row[rr] = t; }
}
